const HARNESS_TEMPLATE = "#!/usr/bin/env -S uv run --script\n# /// script\n# requires-python = \">=3.11\"\n# dependencies = [\n#     \"httpx>=0.27\",\n# ]\n# ///\n\"\"\"\nLive-endpoint validation harness for the serving-capacity model\n(scripts/scenario_model.py; interactive/index.html mirrors it in JS).\n\nThe model predicts four ceilings for a configuration \u2014 cache (warm p5),\ndecode (users at the tok/s floor), latency (users where a miss's mean TTFT\nhits the budget) and saturation (prefill duty 100%) \u2014 and the binding one\nis the smallest. Every one of those is a projection: docs/scenarios.md\n(\"Planning stance\") is explicit that the study is a hypothesis generator\nand that \"comfortable capacity\" is DEFINED as measured SLO capacity, a\nnumber the model cannot produce. This script is that measurement: it\ndrives a LIVE vLLM endpoint with the closed-loop workload the model\nassumes and finds the real limit.\n\n  MEASURED SLO CAPACITY := the largest simulated population meeting\n      p{percentile} TTFT <= ttft_budget_s\n      AND per-user p50 decode >= itl_floor_tok_s\n  over a geometric load ladder bracketing the model's predicted limit.\n\nWorkload (one simulated user = one session, assumption 1 of the planner):\nevery session shares ONE byte-identical system prefix (so vLLM prefix\ncaching engages), carries a per-session context drawn from the model's\nlog-normal (median/sigma; tokens ~ chars/4, and the ACHIEVED prompt_tokens\nare read back from `usage` and reported against the intent), and loops:\nthink (exponential, mean think_time_s) -> send prior context + a\nwarm_turn_tokens turn -> stream the response. With probability miss_rate a\nturn prepends a random salt, making the whole request unmatchable \u2014 the\nmodel's cache miss. Subagent sessions (ratio r, leaner prompts) run the\nsame loop with their OWN byte-stable prefix (subagent_prefix_tokens),\nexactly as Workload prices them \u2014 unless sub_shares_prefix points both\nclasses at the single user prefix.\n\nWhat one run establishes, and what it cannot: the ladder separates the\nceilings only by their observed failure mode (TTFT breach vs decode-floor\nbreach); warm capacity is bounded BELOW unless the run reaches eviction;\ncorrelated-flush tolerance (B*) needs --burst. The verdict table names\nwhich is which \u2014 read the \"what this run does not establish\" trailer\nbefore quoting any number from it.\n\nUsage:\n    uv run validate_deployment.py --dry-run        # offline: plan + sampler self-check\n    uv run validate_deployment.py --base-url http://host:8000/v1\n    uv run validate_deployment.py --burst 8        # B* probe instead of the ladder\n\nCtrl-C at any point prints a partial report over the rungs completed.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport asyncio\nimport json\nimport math\nimport os\nimport random\nimport sys\nimport time\nfrom dataclasses import dataclass, field\n\n# --- BEGIN CONFIG (generated by the interactive explorer) ---\nCONFIG = {\n    # Reference example: 27B / 4xH200 TP4, f = 1%, max_num_batched_tokens 4096.\n    # The explorer replaces this whole block with the configuration on screen.\n    \"endpoint\": {\n        \"base_url\": \"http://localhost:8000/v1\",\n        \"model\": \"Qwen/Qwen3.6-27B-FP8\",\n        \"api_key_env\": \"VLLM_API_KEY\",       # env var NAME, not the key itself\n    },\n    # what the server under test was started with. Informational: nothing is\n    # measured off it, but every prediction below is priced at THIS chunk and\n    # the --json dump carries the block, so an A/B run (e.g. 4,096 vs 32,768)\n    # is self-labeling.\n    \"deployment\": {\n        \"gpus\": \"4xH200\",\n        \"tensor_parallel\": 4,\n        \"replicas\": 1,\n        \"max_num_batched_tokens\": 4_096,\n        \"max_model_len\": 180_000,\n    },\n    \"workload\": {\n        \"system_prefix_tokens\": 15_000,      # shared prefix, identical bytes for all sessions\n        \"user_prompt_median_tokens\": 31_000, # log-normal median of a user session's context\n        \"user_prompt_sigma\": 0.81,           # log-normal shape (sigma of ln L)\n        \"warm_turn_tokens\": 2_000,           # new tokens appended per warm turn\n        \"think_time_s\": 30.0,                # mean turn-to-turn interval (exponential)\n        \"subagent_ratio\": 0.10,              # subagent sessions per user session\n        \"subagent_median_tokens\": 8_000,\n        \"subagent_sigma\": 0.9,\n        \"subagent_prefix_tokens\": 3_000,     # subagents' own lean shared prefix\n        \"sub_shares_prefix\": False,          # True = subagents reuse the user prefix\n        \"miss_rate\": 0.01,                   # per-turn probability of a forced full re-prefill\n        \"max_output_tokens\": 400,            # decoded tokens per turn (OUT_TOKENS_DEFAULT,\n                                             # measured 2026-08-27; was 1,000 assumed)\n    },\n    \"slo\": {\n        \"ttft_budget_s\": 10.0,\n        \"itl_floor_tok_s\": 40,               # the study's hard per-user decode floor\n        \"percentile\": 95,                    # TTFT percentile the SLO is read at\n    },\n    \"predictions\": {\n        \"warm_capacity_p5\": 403,             # user-class warm sessions, p5 (plan column)\n        \"decode_ceiling_users\": 428,         # users at the 40 tok/s p50 floor (mns@40)\n        \"latency_ceiling_users\": 499,        # users where a miss's mean TTFT = budget\n        \"saturation_ceiling_users\": 509,     # users where prefill duty = 100%\n        \"binding_constraint\": \"cache\",       # argmin of the four ceilings\n        \"predicted_limit_users\": 403,        # the binding ceiling's value\n        \"operating_point_users\": 64,         # the load ttft_miss_s / bstar were computed AT\n        \"ttft_miss_s\": 0.92,                 # mean TTFT of a miss at the operating point\n        \"bstar_misses\": 9.8,                 # B*: simultaneous misses drained inside the budget\n        # H9 (PR #37): the decode batch the LOAD produces, not the all-warm\n        # stress point. Arrivals are open-loop, so most of the warm pool is\n        # idle between turns and the batch is far smaller / far faster.\n        \"steady_decode_seqs\": 1.15,          # sequences decoding at the operating point\n                                             # (re-derived 2026-08-27 at 400 out\n                                             # tokens; was 3.11 at the assumed 1,000)\n        \"steady_decode_tok_s\": 817,          # per-user decode at THAT batch size (was 756)\n        # the chunk-size hypothesis. Both are per-SSE-event gaps, ms.\n        \"itl_normal_ms\": 2.2,                # gap with no prefill in the pass\n        \"itl_worst_freeze_ms\": 171,          # last chunk of a 180k cold re-prefill\n    },\n    \"hypotheses\": [\n        \"H-cache: >= 403 user sessions stay warm (p5). This run bounds it below \"\n        \"unless load reaches eviction (watch the effective-cold fraction).\",\n        \"H-decode: per-user p50 decode holds >= 40 tok/s up to ~428 concurrent users.\",\n        \"H-latency: a cache miss's mean TTFT reaches the 10 s budget near ~499 users.\",\n        \"H-saturation: prefill duty reaches 100% near ~509 users; above it the queue \"\n        \"has no steady state.\",\n        \"H-binding: the binding constraint is 'cache' \u2014 measured SLO capacity should \"\n        \"land near 403 users.\",\n        \"H-ttft-miss: a forced miss's mean TTFT at the operating point is ~0.92 s.\",\n        \"H-burst (needs --burst): a simultaneous flush of <= 9 misses (B* = 9.8) \"\n        \"drains inside the TTFT budget; a larger one does not.\",\n        # --- the two the reference CONFIG never carried ----------------------\n        \"H-steady (H9): at the operating point the decode batch holds ~1.2 \"\n        \"sequences at ~817 tok/s each \u2014 NOT the whole warm pool at the stress \"\n        \"figure. Read against the measured concurrent-decode count, not the \"\n        \"population. (Re-derived 2026-08-27 at the measured 400 output \"\n        \"tokens; the pre-measurement reference was ~3.1 at ~756.)\",\n        \"H-itl-spike: the worst freeze behind one chunk of a 180k cold \"\n        \"re-prefill is ~171 ms [110-260] at max_num_batched_tokens=4096 vs \"\n        \"~1,289 ms [640-1,980] at 32,768. Brackets are the study's MFU range \"\n        \"([30-60] around 45% when these figures were generated; the bracket \"\n        \"tightened to [35-55] on 2026-08-27, research/prefill.md #1 \u2014 the ms \"\n        \"ranges here still quote the wider band): the spike MAGNITUDE \"\n        \"scales ~inversely with MFU and is unvalidated, but the RATIO between \"\n        \"the two settings does not \u2014 quote the ratio, not the milliseconds. \"\n        \"Read it on the INTER-TOKEN GAPS table, never on decode p50 (a mean \"\n        \"over the stream is nearly blind to a freeze). NOTE the 4k bracket \"\n        \"straddles a 250 ms freeze threshold, which is why the default is 100 \"\n        \"and why the freeze ladder exists.\",\n        \"H-itl-mean: the normal inter-token gap (~2.2 ms) and total stall time \"\n        \"are ~unchanged between the two chunk settings \u2014 prefill FLOPs \"\n        \"telescope, so only the per-pass weight-stream overhead does not \"\n        \"(~+1.9% total machine time at 4k). CAVEAT: the exact invariance is a \"\n        \"property of the flat-MFU pricing; under the per-pass-overhead pricing \"\n        \"the explorer uses, the mean moves by that ~1.9%. Also note ~2.2 ms is \"\n        \"near the client-side timing floor \u2014 check the 'floor' column before \"\n        \"reading anything into this row.\",\n    ],\n}\n# --- END CONFIG ---\n\nDEFAULT_RUNGS = \"0.25,0.5,0.75,1,1.25,1.5,2\"\n\n# Freeze thresholds reported as a LADDER, not a single number. A lone\n# threshold is load-bearing in the worst way: set it at 250 ms and a\n# configuration whose worst freeze is 171 ms reads as \"zero freezes\", turning\n# a 7.5x quantitative win into a spurious qualitative one. The ladder shows\n# the distribution and lets the reader pick.\nFREEZE_LADDER_MS = (50.0, 100.0, 250.0, 500.0, 1000.0)\n\n\n# ============================================================================\n# small numerics (no numpy: this file must run standalone from a download)\n# ============================================================================\ndef pct(xs, q: float) -> float:\n    \"\"\"Linear-interpolation percentile; nan on empty input.\"\"\"\n    if not xs:\n        return float(\"nan\")\n    s = sorted(xs)\n    if len(s) == 1:\n        return float(s[0])\n    pos = (len(s) - 1) * q / 100.0\n    lo = math.floor(pos)\n    frac = pos - lo\n    hi = min(lo + 1, len(s) - 1)\n    return float(s[lo] * (1 - frac) + s[hi] * frac)\n\n\ndef fmt(x, unit: str = \"\", nd: int = 2) -> str:\n    if x is None or (isinstance(x, float) and not math.isfinite(x)):\n        return \"-\"\n    return f\"{x:.{nd}f}{unit}\"\n\n\n# ============================================================================\n# synthetic text  (tokens ~ chars / chars_per_token; the run reads back the\n# ACHIEVED prompt_tokens from `usage` and reports the ratio, closing the loop)\n# ============================================================================\n_VOCAB = (\"the build failed on stage three because a header moved and the cache \"\n          \"key did not include it so the runner reused a stale object then the \"\n          \"linker saw two symbols with one name and gave up while the test \"\n          \"suite kept polling a socket that nothing owned anymore\").split()\n\n\ndef make_text(rng: random.Random, tokens: float, cpt: float) -> str:\n    \"\"\"~`tokens` worth of plain prose (cpt chars per token, measured later).\"\"\"\n    budget = max(int(tokens * cpt), 1)\n    out, n = [], 0\n    while n < budget:\n        w = _VOCAB[rng.randrange(len(_VOCAB))]\n        out.append(w)\n        n += len(w) + 1\n    return \" \".join(out)[:budget]\n\n\ndef draw_session_tokens(rng: random.Random, median: float, sigma: float,\n                        prefix: float, cap: float) -> int:\n    \"\"\"One session's full prompt length: log-normal(median, sigma), clipped to\n    [prefix, cap] exactly as Workload.sample clips (a prompt always contains\n    at least its shared prefix, never more than the cap).\"\"\"\n    full = rng.lognormvariate(math.log(median), sigma)\n    return int(min(max(full, prefix), cap))\n\n\n# ============================================================================\n# measurement records\n# ============================================================================\n@dataclass\nclass Turn:\n    uid: int\n    is_sub: bool\n    kind: str                 # \"first\" (session establishment) | \"hit\" | \"miss\"\n    t_start: float\n    ttft: float | None = None\n    decode_tps: float | None = None\n    ptok_intended: int = 0\n    ptok_achieved: int | None = None\n    ctok: int | None = None\n    error: str | None = None\n    # --- inter-token gap stats (the ITL-spike evidence) ---------------------\n    # decode_tps above is a MEAN over the whole stream and is nearly blind to a\n    # freeze: a single 1.3 s stall inside a 1,000-token response otherwise\n    # running at 200 tok/s reads as ~159 tok/s \u2014 a 20% dip standing in for a\n    # 260x spike. These fields keep the distribution the mean throws away.\n    # Gaps are measured per SSE EVENT, not per token; chunk_tok_ratio in the\n    # report says how far apart those two are on this endpoint.\n    itl_p50: float | None = None      # s, median gap within this response\n    itl_max: float | None = None      # s, worst gap within this response\n    itl_min: float | None = None      # s, smallest gap \u2014 the CLIENT FLOOR probe\n    n_gaps: int = 0\n    n_freeze: int = 0                 # gaps >= the headline freeze threshold\n    stall_s: float = 0.0              # total time inside those gaps\n    n_freeze_at: tuple = ()           # counts, one per FREEZE_LADDER_MS entry\n    stall_at: tuple = ()              # summed seconds, same order\n    span_s: float | None = None       # t_last - t_first\n    t_end: float | None = None        # monotonic end-of-stream (last chunk)\n    n_chunks: int = 0\n\n\n@dataclass\nclass RungResult:\n    pop: int                  # user-class sessions (the population axis)\n    n_sub: int\n    n_turns: int = 0\n    n_hit: int = 0\n    n_miss: int = 0\n    n_err: int = 0\n    ttft_hit_p50: float = float(\"nan\")\n    ttft_hit_pX: float = float(\"nan\")\n    ttft_miss_p50: float = float(\"nan\")\n    ttft_miss_pX: float = float(\"nan\")\n    ttft_miss_mean: float = float(\"nan\")\n    ttft_all_pX: float = float(\"nan\")\n    decode_p50: float = float(\"nan\")\n    # --- ITL gap distribution (see Turn) ---\n    itl_p50_ms: float = float(\"nan\")        # the normal inter-token gap\n    itl_worst_p50_ms: float = float(\"nan\")  # typical worst freeze, per response\n    itl_worst_p95_ms: float = float(\"nan\")  # unlucky response's worst freeze\n    # max-of-maxes: sample-size biased (the arm with more responses draws more\n    # from the same tail), so it is a footnote, never a headline comparison\n    itl_max_ms: float = float(\"nan\")\n    itl_floor_ms: float = float(\"nan\")      # smallest gap seen \u2014 CLIENT FLOOR\n    freeze_per_ktok: float = float(\"nan\")   # freezes per 1k DECODED TOKENS\n    stall_frac: float = float(\"nan\")        # share of stream wall-time stalled\n    stall_ms_per_ktok: float = float(\"nan\")  # stalled ms per 1k decoded tokens\n    freeze_ladder: list = field(default_factory=list)  # per FREEZE_LADDER_MS\n    chunk_tok_ratio: float = float(\"nan\")   # tokens per SSE event (1.0 = per-token)\n    achieved_rps: float = float(\"nan\")\n    offered_rps: float = float(\"nan\")\n    evict_frac: float = float(\"nan\")   # hit-intended turns that look cold (heuristic)\n    ptok_ratio: float = float(\"nan\")   # achieved / intended prompt tokens, median\n    passed: bool = False\n    reasons: list = field(default_factory=list)\n    blown: bool = False                # SLOs clearly blown -> ladder stops here\n    partial: bool = False              # interrupted mid-window: shown, never counted\n\n\n# ============================================================================\n# one streamed request against the OpenAI-compatible /v1/completions\n# ============================================================================\nasync def send_turn(client, args, cfg, prompt: str, turn: Turn) -> str:\n    \"\"\"Stream one completion; fills `turn` in place, returns the response text\n    (appended to the session so the next warm turn extends the cached run).\"\"\"\n    ep = cfg[\"endpoint\"]\n    payload = {\n        \"model\": args.model or ep[\"model\"],\n        \"prompt\": prompt,\n        \"max_tokens\": cfg[\"workload\"][\"max_output_tokens\"],\n        \"temperature\": 0.7,\n        \"stream\": True,\n        \"stream_options\": {\"include_usage\": True},\n    }\n    if not args.no_ignore_eos:\n        # vLLM extension: guarantees max_output_tokens of decode per turn, so\n        # decode tok/s is measured over a fixed-length stream, not over\n        # whatever an early EOS leaves. Strict non-vLLM endpoints: disable.\n        payload[\"ignore_eos\"] = True\n    headers = {}\n    key = os.environ.get(args.api_key_env or ep[\"api_key_env\"] or \"\", \"\")\n    if key:\n        headers[\"Authorization\"] = f\"Bearer {key}\"\n\n    base = (args.base_url or ep[\"base_url\"]).rstrip(\"/\")\n    t0 = time.monotonic()\n    t_first = t_last = None\n    n_chunks, text, usage = 0, [], None\n    gaps: list[float] = []\n    try:\n        async with client.stream(\"POST\", f\"{base}/completions\", json=payload,\n                                 headers=headers,\n                                 timeout=args.request_timeout_s) as r:\n            r.raise_for_status()\n            async for line in r.aiter_lines():\n                if not line.startswith(\"data:\"):\n                    continue\n                data = line[5:].strip()\n                if data == \"[DONE]\":\n                    break\n                obj = json.loads(data)\n                if obj.get(\"usage\"):\n                    usage = obj[\"usage\"]\n                ch = obj.get(\"choices\") or []\n                if ch and ch[0].get(\"text\"):\n                    now = time.monotonic()\n                    if t_first is None:\n                        t_first = now\n                        turn.ttft = now - t0\n                    else:\n                        gaps.append(now - t_last)\n                    t_last = now\n                    n_chunks += 1\n                    text.append(ch[0][\"text\"])\n    except asyncio.CancelledError:\n        raise\n    except Exception as e:  # connection, HTTP status, timeout, bad JSON\n        turn.error = f\"{type(e).__name__}: {e}\"[:200]\n        return \"\"\n\n    if usage:\n        turn.ptok_achieved = usage.get(\"prompt_tokens\")\n        turn.ctok = usage.get(\"completion_tokens\")\n    n_tok = turn.ctok if turn.ctok else n_chunks\n    # span_s is set whenever the stream had >= 2 content chunks \u2014 the SAME\n    # condition that makes `gaps` non-empty. It used to also require\n    # n_tok > 1, which a server reporting completion_tokens=1 on a multi-chunk\n    # stream could fail: the turn then carried stall_s with no span, inflating\n    # any ratio built from the two. decode_tps keeps the n_tok gate (a rate\n    # needs a token count); span does not.\n    if t_first is not None and t_last is not None and t_last > t_first:\n        turn.span_s = t_last - t_first\n        turn.t_end = t_last\n        if n_tok > 1:\n            turn.decode_tps = (n_tok - 1) / (t_last - t_first)\n    turn.n_chunks = n_chunks\n    if gaps:\n        freeze_s = args.freeze_threshold_ms / 1e3\n        big = [g for g in gaps if g >= freeze_s]\n        turn.itl_p50 = pct(gaps, 50)\n        turn.itl_max = max(gaps)\n        turn.itl_min = min(gaps)\n        turn.n_gaps = len(gaps)\n        turn.n_freeze = len(big)\n        turn.stall_s = sum(big)\n        turn.n_freeze_at = tuple(\n            sum(1 for g in gaps if g >= t / 1e3) for t in FREEZE_LADDER_MS)\n        turn.stall_at = tuple(\n            sum(g for g in gaps if g >= t / 1e3) for t in FREEZE_LADDER_MS)\n    return \"\".join(text)\n\n\n# ============================================================================\n# closed-loop session\n# ============================================================================\nasync def user_loop(client, args, cfg, uid: int, is_sub: bool,\n                    system_prefix: str, sub_prefix: str, turns: list,\n                    stop: asyncio.Event, stagger_s: float):\n    wl = cfg[\"workload\"]\n    rng = random.Random((args.seed << 20) ^ uid)\n    cpt = args.chars_per_token\n    median = wl[\"subagent_median_tokens\"] if is_sub else wl[\"user_prompt_median_tokens\"]\n    sigma = wl[\"subagent_sigma\"] if is_sub else wl[\"user_prompt_sigma\"]\n    # each request class carries ITS OWN byte-stable prefix, exactly as\n    # Workload.sample prices it: subagents get the lean sub prefix unless\n    # sub_shares_prefix points them at the user prefix (the old behaviour\n    # \u2014 always the user prefix \u2014 silently tested a ~3x lighter subagent\n    # workload than the one the predictions were computed on)\n    own_sub = is_sub and not wl.get(\"sub_shares_prefix\", False)\n    prefix_tok = wl.get(\"subagent_prefix_tokens\", 3_000) if own_sub \\\n        else wl[\"system_prefix_tokens\"]\n    prefix_txt = sub_prefix if own_sub else system_prefix\n    full = draw_session_tokens(rng, median, sigma, prefix_tok,\n                               args.context_cap_tokens)\n    # per-session unique context on top of this class's shared prefix\n    ctx = make_text(rng, max(full - prefix_tok, 0), cpt)\n    history = \"\"\n    n_turn = 0\n    cap = args.turns_per_user or math.inf\n\n    await asyncio.sleep(stagger_s)          # spread session establishment over the ramp\n    while not stop.is_set() and n_turn < cap:\n        first = n_turn == 0\n        if not first:\n            # exponential think time; wake early if the rung ends\n            try:\n                await asyncio.wait_for(stop.wait(),\n                                       rng.expovariate(1.0 / wl[\"think_time_s\"]))\n                break\n            except asyncio.TimeoutError:\n                pass\n        is_miss = (not first) and rng.random() < wl[\"miss_rate\"]\n        # a salt ahead of the prefix makes the WHOLE request unmatchable \u2014 the\n        # model's cache miss (full re-prefill), applied to this turn only\n        salt = f\"[miss-salt {rng.getrandbits(64):016x}] \" if is_miss else \"\"\n        turn_text = \"\" if first else \"\\n\" + make_text(rng, wl[\"warm_turn_tokens\"], cpt)\n        prompt = salt + prefix_txt + \"\\n\" + ctx + history + turn_text\n        turn = Turn(uid=uid, is_sub=is_sub,\n                    kind=\"first\" if first else (\"miss\" if is_miss else \"hit\"),\n                    t_start=time.monotonic(),\n                    ptok_intended=int(len(prompt) / cpt))\n        turns.append(turn)\n        reply = await send_turn(client, args, cfg, prompt, turn)\n        # the response joins the context: the next warm turn extends the cached\n        # sequence exactly the way a real agentic session does\n        history += turn_text + reply\n        n_turn += 1\n\n\n# ============================================================================\n# one ladder rung\n# ============================================================================\ndef eval_rung(pop: int, n_sub: int, turns: list, measure_start: float,\n              cfg, args) -> RungResult:\n    slo, wl = cfg[\"slo\"], cfg[\"workload\"]\n    p = slo[\"percentile\"]\n    res = RungResult(pop=pop, n_sub=n_sub)\n\n    measured = [t for t in turns\n                if t.t_start >= measure_start and t.kind in (\"hit\", \"miss\")]\n    res.n_err = sum(1 for t in measured if t.error)\n    ok = [t for t in measured if not t.error and t.ttft is not None]\n    hit = [t for t in ok if t.kind == \"hit\"]\n    miss = [t for t in ok if t.kind == \"miss\"]\n    res.n_turns, res.n_hit, res.n_miss = len(ok), len(hit), len(miss)\n\n    res.ttft_hit_p50 = pct([t.ttft for t in hit], 50)\n    res.ttft_hit_pX = pct([t.ttft for t in hit], p)\n    res.ttft_miss_p50 = pct([t.ttft for t in miss], 50)\n    res.ttft_miss_pX = pct([t.ttft for t in miss], p)\n    if miss:\n        res.ttft_miss_mean = sum(t.ttft for t in miss) / len(miss)\n    res.ttft_all_pX = pct([t.ttft for t in ok], p)\n\n    # per-user decode: median within each user, then p50 across users \u2014 the\n    # model's \"per-user p50\" is a population statistic, not a turn statistic\n    by_user: dict[int, list] = {}\n    for t in ok:\n        if t.decode_tps is not None:\n            by_user.setdefault(t.uid, []).append(t.decode_tps)\n    res.decode_p50 = pct([pct(v, 50) for v in by_user.values()], 50)\n\n    # ITL gap distribution. decode_p50 above answers \"how fast on average\";\n    # these answer \"what did it feel like\" \u2014 the chunk-size hypothesis lives\n    # entirely here, because chunking moves the tail and leaves the mean flat.\n    # Every turn here has span_s (send_turn sets it under the same condition\n    # that makes gaps non-empty), so numerator and denominator of any ratio\n    # below run over the SAME set.\n    g = [t for t in ok if t.n_gaps > 0 and t.span_s]\n    if g:\n        res.itl_p50_ms = pct([t.itl_p50 for t in g], 50) * 1e3\n        worst = [t.itl_max for t in g]\n        res.itl_worst_p50_ms = pct(worst, 50) * 1e3\n        res.itl_worst_p95_ms = pct(worst, 95) * 1e3\n        res.itl_max_ms = max(worst) * 1e3\n        # the client floor: the smallest gap the loop was able to resolve. If\n        # this is a material fraction of itl_p50_ms, the \"normal gap\" reading\n        # is client-side scheduling, not server behaviour.\n        res.itl_floor_ms = min(t.itl_min for t in g) * 1e3\n        span = sum(t.span_s for t in g)\n        if span > 0:\n            res.stall_frac = sum(t.stall_s for t in g) / span\n\n        # per-TOKEN rates need a token count, not a gap count: gaps are per\n        # SSE event and an event may carry several tokens. Turns without a\n        # usage report cannot be priced per token, so both sums run over the\n        # subset that has one.\n        g_tok = [t for t in g if t.ctok]\n        ctoks = sum(t.ctok for t in g_tok)\n        if ctoks:\n            res.freeze_per_ktok = 1e3 * sum(t.n_freeze for t in g_tok) / ctoks\n            res.stall_ms_per_ktok = 1e6 * sum(t.stall_s for t in g_tok) / ctoks\n            res.chunk_tok_ratio = ctoks / sum(t.n_chunks for t in g_tok)\n            res.freeze_ladder = [\n                {\"threshold_ms\": thr,\n                 \"per_ktok\": 1e3 * sum(t.n_freeze_at[i] for t in g_tok) / ctoks,\n                 \"stall_ms_per_ktok\":\n                     1e6 * sum(t.stall_at[i] for t in g_tok) / ctoks}\n                for i, thr in enumerate(FREEZE_LADDER_MS)]\n\n    res.achieved_rps = len(measured) / args.measure_s\n    res.offered_rps = (pop + n_sub) / wl[\"think_time_s\"]\n\n    # eviction heuristic (the baseline's warm/cold classifier): a hit-intended\n    # turn whose TTFT is >= 0.4x the median forced-miss TTFT re-prefilled \u2014 its\n    # cached run was evicted. A heuristic, flagged as such in the report.\n    if hit and miss and math.isfinite(res.ttft_miss_p50):\n        thresh = 0.4 * res.ttft_miss_p50\n        res.evict_frac = sum(1 for t in hit if t.ttft >= thresh) / len(hit)\n\n    ratios = [t.ptok_achieved / t.ptok_intended for t in ok\n              if t.ptok_achieved and t.ptok_intended]\n    res.ptok_ratio = pct(ratios, 50)\n\n    # SLO verdict for this rung\n    budget, floor = slo[\"ttft_budget_s\"], slo[\"itl_floor_tok_s\"]\n    err_frac = res.n_err / max(len(measured), 1)\n    if not ok:\n        res.reasons.append(\"no successful turns in the measure window\")\n        res.blown = True\n    else:\n        if err_frac > 0.05:\n            res.reasons.append(f\"error rate {err_frac:.0%}\")\n        if res.ttft_all_pX > budget:\n            res.reasons.append(f\"p{p} TTFT {res.ttft_all_pX:.2f}s > {budget:g}s\")\n        if math.isfinite(res.decode_p50) and res.decode_p50 < floor:\n            res.reasons.append(f\"decode p50 {res.decode_p50:.1f} < {floor:g} tok/s\")\n        res.blown = (res.ttft_all_pX > 2 * budget\n                     or (math.isfinite(res.decode_p50)\n                         and res.decode_p50 < 0.5 * floor)\n                     or err_frac > 0.20)\n    res.passed = not res.reasons\n    return res\n\n\nasync def run_rung(client, args, cfg, pop: int, state: dict) -> RungResult:\n    wl = cfg[\"workload\"]\n    n_sub = round(pop * wl[\"subagent_ratio\"])\n    turns: list[Turn] = []\n    state[\"current\"] = (pop, n_sub, turns, None)\n    stop = asyncio.Event()\n    system_prefix = state[\"system_prefix\"]\n\n    tasks = []\n    rng = random.Random(args.seed ^ pop)\n    for i in range(pop + n_sub):\n        tasks.append(asyncio.create_task(user_loop(\n            client, args, cfg, uid=pop * 100_000 + i, is_sub=(i >= pop),\n            system_prefix=system_prefix, sub_prefix=state[\"sub_prefix\"],\n            turns=turns, stop=stop,\n            stagger_s=rng.uniform(0, max(args.ramp_s, 1.0)))))\n    t0 = time.monotonic()\n    measure_start = t0 + args.ramp_s\n    state[\"current\"] = (pop, n_sub, turns, measure_start)\n    try:\n        await asyncio.sleep(args.ramp_s + args.measure_s)\n    finally:\n        stop.set()\n        for t in tasks:\n            t.cancel()\n        await asyncio.gather(*tasks, return_exceptions=True)\n\n    res = eval_rung(pop, n_sub, turns, measure_start, cfg, args)\n    state[\"rungs\"].append(res)\n    state[\"current\"] = None\n    return res\n\n\n# ============================================================================\n# burst probe  (--burst N: validates B*, the correlated-flush tolerance)\n# ============================================================================\nasync def run_burst(client, args, cfg, state: dict):\n    \"\"\"From steady standing load, fire N simultaneous forced misses and time\n    the drain. B* predicts the largest N whose LAST first-token still lands\n    inside the TTFT budget (spike_tolerance in scenario_model.py).\"\"\"\n    wl = cfg[\"workload\"]\n    pred = cfg[\"predictions\"]\n    # standing load defaults to the OPERATING POINT the B* prediction was\n    # computed at (old default 0.5 x limit drained the burst into a\n    # different duty cycle than the one that priced it)\n    pop = args.burst_users or max(1, round(\n        pred.get(\"operating_point_users\")\n        or 0.5 * pred[\"predicted_limit_users\"]))\n    n_sub = round(pop * wl[\"subagent_ratio\"])\n    n = args.burst\n    print(f\"\\nBURST PROBE: standing load {pop} users (+{n_sub} subagents), \"\n          f\"ramp {args.ramp_s:g}s, then {n} simultaneous forced misses \"\n          f\"(predicted B* = {pred['bstar_misses']:g})\")\n\n    turns: list[Turn] = []\n    stop = asyncio.Event()\n    rng = random.Random(args.seed ^ 0xB0057)\n    tasks = [asyncio.create_task(user_loop(\n        client, args, cfg, uid=900_000 + i, is_sub=(i >= pop),\n        system_prefix=state[\"system_prefix\"], sub_prefix=state[\"sub_prefix\"],\n        turns=turns, stop=stop,\n        stagger_s=rng.uniform(0, max(args.ramp_s, 1.0))))\n        for i in range(pop + n_sub)]\n    try:\n        await asyncio.sleep(args.ramp_s)\n\n        async def one_miss(i: int) -> Turn:\n            r = random.Random((args.seed << 8) ^ (0xF00D + i))\n            full = draw_session_tokens(r, wl[\"user_prompt_median_tokens\"],\n                                       wl[\"user_prompt_sigma\"],\n                                       wl[\"system_prefix_tokens\"],\n                                       args.context_cap_tokens)\n            salt = f\"[miss-salt {r.getrandbits(64):016x}] \"\n            prompt = (salt + state[\"system_prefix\"] + \"\\n\"\n                      + make_text(r, max(full - wl[\"system_prefix_tokens\"], 0),\n                                  args.chars_per_token))\n            t = Turn(uid=990_000 + i, is_sub=False, kind=\"miss\",\n                     t_start=time.monotonic(),\n                     ptok_intended=int(len(prompt) / args.chars_per_token))\n            await send_turn(client, args, cfg, prompt, t)\n            return t\n\n        t_fire = time.monotonic()\n        burst_turns = await asyncio.gather(*[one_miss(i) for i in range(n)])\n    finally:\n        stop.set()\n        for t in tasks:\n            t.cancel()\n        await asyncio.gather(*tasks, return_exceptions=True)\n\n    ok = [t for t in burst_turns if t.ttft is not None and not t.error]\n    result = {\n        \"n\": n, \"standing_users\": pop,\n        \"n_ok\": len(ok), \"n_err\": n - len(ok),\n        # drain: fire -> the LAST request's first token (all fired together,\n        # so last first-token = the fluid model's T_drain, whatever the\n        # scheduler's discipline \u2014 see burst_drain_seconds)\n        \"drain_s\": (max(t.t_start + t.ttft for t in ok) - t_fire) if ok else None,\n        \"last_ttft_s\": max((t.ttft for t in ok), default=None),\n        \"ttft_p50_s\": pct([t.ttft for t in ok], 50),\n    }\n\n    # What the STANDING load felt while the burst was draining. This is the\n    # chunk-size hypothesis in its purest form: the burst is a controlled\n    # cold-prefill event, and these are the decoders it lands on. It is also\n    # the RELIABLE place to read a spike \u2014 the standing load is small (the\n    # steady-state decode batch, not a high ladder rung), so client event-loop\n    # contention cannot manufacture gaps the way it can under the ladder.\n    # The window is \"request in flight at fire time\": t_end is the real\n    # end-of-stream (turns that never got a first token have no t_end and are\n    # already excluded by the n_gaps > 0 filter).\n    victims = [t for t in turns\n               if t.n_gaps > 0 and t.t_end and t.t_start <= t_fire <= t.t_end]\n    if victims:\n        worst = [t.itl_max for t in victims]\n        result[\"standing_n\"] = len(victims)\n        result[\"standing_itl_p50_ms\"] = pct([t.itl_p50 for t in victims], 50) * 1e3\n        result[\"standing_worst_p50_ms\"] = pct(worst, 50) * 1e3\n        result[\"standing_worst_max_ms\"] = max(worst) * 1e3\n        result[\"standing_floor_ms\"] = min(t.itl_min for t in victims) * 1e3\n        # per DECODED TOKEN, not per gap \u2014 see eval_rung\n        v_tok = [t for t in victims if t.ctok]\n        ctoks = sum(t.ctok for t in v_tok)\n        result[\"standing_freeze_per_ktok\"] = (\n            1e3 * sum(t.n_freeze for t in v_tok) / ctoks) if ctoks else None\n        result[\"standing_freeze_ladder\"] = [\n            {\"threshold_ms\": thr,\n             \"per_ktok\": 1e3 * sum(t.n_freeze_at[i] for t in v_tok) / ctoks}\n            for i, thr in enumerate(FREEZE_LADDER_MS)] if ctoks else None\n\n    state[\"burst\"] = result\n    print(f\"  burst: {len(ok)}/{n} answered | TTFT p50 {fmt(result['ttft_p50_s'], 's')} \"\n          f\"| last first-token {fmt(result['last_ttft_s'], 's')} \"\n          f\"| drain {fmt(result['drain_s'], 's')}\")\n    if victims:\n        print(f\"  standing load hit by it: {len(victims)} responses in flight | \"\n              f\"normal gap {fmt(result['standing_itl_p50_ms'], ' ms', 1)} | \"\n              f\"worst gap p50 {fmt(result['standing_worst_p50_ms'], ' ms', 0)} | \"\n              f\"worst seen {fmt(result['standing_worst_max_ms'], ' ms', 0)} | \"\n              f\"client floor {fmt(result['standing_floor_ms'], ' ms', 2)}\")\n        if result.get(\"standing_freeze_ladder\"):\n            lad = \" \".join(f\"{e['threshold_ms']:g}ms:{e['per_ktok']:.2f}\"\n                           for e in result[\"standing_freeze_ladder\"])\n            print(f\"  freezes per 1k tokens by threshold: {lad}\")\n\n\n# ============================================================================\n# verdicts\n# ============================================================================\nCHECK, CROSS, TILDE = \"\u2713\", \"\u2717\", \"~\"\n\n\ndef bracket_verdict(pred: float, lo: float | None, hi: float | None) -> tuple:\n    \"\"\"Compare a predicted ceiling against the measured (largest-pass,\n    smallest-fail] population bracket. lo/hi None = side not observed.\n    ~ means within 25% of the nearest observed edge.\"\"\"\n    if pred is None:\n        return TILDE, \"no prediction\"\n    if lo is None and hi is None:\n        return TILDE, \"no data\"\n    if hi is None:                       # never failed: lower bound only\n        if pred >= lo:\n            return TILDE, f\"not reached (measured >= {lo:g}, predicted {pred:g})\"\n        if lo <= 1.25 * pred:\n            return TILDE, f\"measured >= {lo:g}, within 25% above prediction\"\n        return CROSS, f\"passed at {lo:g} > 1.25x predicted {pred:g} (model conservative)\"\n    if lo is None:                       # every rung failed: upper bound only\n        if pred <= hi:\n            return TILDE, f\"capacity < {hi:g}; prediction {pred:g} not excluded\"\n        if pred <= hi / 0.75:\n            return TILDE, f\"capacity < {hi:g}, within 25% below prediction\"\n        return CROSS, f\"failed at {hi:g} < 0.75x predicted {pred:g} (model optimistic)\"\n    if lo <= pred <= hi:\n        return CHECK, f\"predicted {pred:g} inside measured ({lo:g}, {hi:g}]\"\n    edge = lo if pred < lo else hi\n    if 0.75 <= pred / edge <= 1.25:\n        return TILDE, f\"predicted {pred:g} within 25% of measured ({lo:g}, {hi:g}]\"\n    return CROSS, f\"predicted {pred:g} outside measured ({lo:g}, {hi:g}]\"\n\n\ndef print_report(state: dict, cfg, args, interrupted: bool = False):\n    slo, pred = cfg[\"slo\"], cfg[\"predictions\"]\n    p = slo[\"percentile\"]\n    rungs: list[RungResult] = list(state[\"rungs\"])\n    # a partially-measured current rung still carries information on Ctrl-C\n    if interrupted and state.get(\"current\"):\n        pop, n_sub, turns, ms = state[\"current\"]\n        if ms is not None and any(t.t_start >= ms for t in turns):\n            r = eval_rung(pop, n_sub, turns, ms, cfg, args)\n            r.partial = True           # shown for orientation, excluded from verdicts\n            rungs.append(r)\n\n    print(\"\\n\" + \"=\" * 78)\n    print(\"VALIDATION REPORT\" + (\"  [INTERRUPTED \u2014 partial]\" if interrupted else \"\"))\n    print(\"=\" * 78)\n\n    if rungs:\n        print(f\"\\n{'users':>6} {'turns':>6} {'hit':>5} {'miss':>5} {'err':>4} \"\n              f\"{'TTFT hit p50/p' + str(p):>17} {'TTFT miss p50/p' + str(p):>18} \"\n              f\"{'dec p50':>8} {'req/s':>6} {'verdict'}\")\n        for r in rungs:\n            verdict = \"PASS\" if r.passed else \"FAIL: \" + \"; \".join(r.reasons)\n            if r.partial:\n                verdict += \" [partial \u2014 not counted]\"\n            print(f\"{r.pop:>6} {r.n_turns:>6} {r.n_hit:>5} {r.n_miss:>5} \"\n                  f\"{r.n_err:>4} \"\n                  f\"{fmt(r.ttft_hit_p50, '', 2):>8}/{fmt(r.ttft_hit_pX, 's', 2):<8} \"\n                  f\"{fmt(r.ttft_miss_p50, '', 2):>8}/{fmt(r.ttft_miss_pX, 's', 2):<9} \"\n                  f\"{fmt(r.decode_p50, '', 1):>8} {fmt(r.achieved_rps, '', 2):>6} \"\n                  f\"{verdict}\")\n        # ---- ITL gap table: what the chunk size actually moves -------------\n        if any(math.isfinite(r.itl_p50_ms) for r in rungs):\n            thr = args.freeze_threshold_ms\n            print(f\"\\nINTER-TOKEN GAPS (freeze = a gap >= {thr:g} ms)\")\n            print(f\"{'users':>6} {'normal p50':>11} {'worst/resp p50':>15} \"\n                  f\"{'worst/resp p95':>15} {'freezes/ktok':>13} \"\n                  f\"{'stall ms/ktok':>14} {'stalled':>8} {'tok/evt':>8} \"\n                  f\"{'floor':>8}\")\n            for r in rungs:\n                stalled = (r.stall_frac * 100 if math.isfinite(r.stall_frac)\n                           else float(\"nan\"))\n                print(f\"{r.pop:>6} {fmt(r.itl_p50_ms, ' ms', 1):>11} \"\n                      f\"{fmt(r.itl_worst_p50_ms, ' ms', 0):>15} \"\n                      f\"{fmt(r.itl_worst_p95_ms, ' ms', 0):>15} \"\n                      f\"{fmt(r.freeze_per_ktok, '', 1):>13} \"\n                      f\"{fmt(r.stall_ms_per_ktok, '', 0):>14} \"\n                      f\"{fmt(stalled, '%', 1):>8} \"\n                      f\"{fmt(r.chunk_tok_ratio, '', 2):>8} \"\n                      f\"{fmt(r.itl_floor_ms, ' ms', 2):>8}\")\n            print(\"  worst-seen (max of maxes, sample-size biased \u2014 footnote \"\n                  \"only): \"\n                  + \", \".join(f\"{r.pop}u {fmt(r.itl_max_ms, ' ms', 0)}\"\n                              for r in rungs))\n\n            # --- comparability and validity guards, per rung ----------------\n            for r in rungs:\n                if (math.isfinite(r.chunk_tok_ratio)\n                        and abs(r.chunk_tok_ratio - 1.0) > 0.05):\n                    print(f\"  WARNING [{r.pop}u]: {r.chunk_tok_ratio:.2f} tokens \"\n                          \"per SSE event. Gap columns are per EVENT: this rung \"\n                          \"is NOT directly comparable with a run whose ratio \"\n                          \"differs. Compare freezes/ktok and stall ms/ktok \"\n                          \"(per-token, ratio-free) instead.\")\n                if (math.isfinite(r.itl_floor_ms) and math.isfinite(r.itl_p50_ms)\n                        and r.itl_p50_ms > 0\n                        and r.itl_floor_ms > 0.10 * r.itl_p50_ms):\n                    print(f\"  WARNING [{r.pop}u]: client floor \"\n                          f\"{r.itl_floor_ms:.2f} ms is >10% of the normal gap \"\n                          f\"{r.itl_p50_ms:.2f} ms \u2014 the event loop, not the \"\n                          \"server, may be setting these gaps. Prefer the burst \"\n                          \"probe at the operating point for spike claims.\")\n\n            # the headline threshold must sit BELOW the freeze it is meant to\n            # catch, or the arm being advocated for reads as 'zero freezes'\n            pw = pred.get(\"itl_worst_freeze_ms\")\n            if pw and thr > pw:\n                print(f\"  WARNING: --freeze-threshold-ms {thr:g} exceeds this \"\n                      f\"config's PREDICTED worst freeze ({pw:g} ms). \"\n                      \"freezes/ktok and stalled% will read ~0 whatever the \"\n                      \"truth. Use the ladder below, or lower the threshold.\")\n\n            if any(r.freeze_ladder for r in rungs):\n                print(\"\\n  FREEZE LADDER \u2014 freezes per 1k tokens at each \"\n                      \"threshold (no single threshold is load-bearing)\")\n                head = \"\".join(f\"{t:g} ms\".rjust(11) for t in FREEZE_LADDER_MS)\n                print(f\"  {'users':>6}{head}\")\n                for r in rungs:\n                    if not r.freeze_ladder:\n                        continue\n                    row = \"\".join(fmt(e[\"per_ktok\"], '', 2).rjust(11)\n                                  for e in r.freeze_ladder)\n                    print(f\"  {r.pop:>6}{row}\")\n\n        ratios = [r.ptok_ratio for r in rungs if math.isfinite(r.ptok_ratio)]\n        if ratios:\n            med = pct(ratios, 50)\n            print(f\"\\nachieved/intended prompt tokens (median): {med:.2f} \"\n                  f\"(tokens ~ chars/{args.chars_per_token:g}; if far from 1.0, \"\n                  f\"re-run with --chars-per-token {args.chars_per_token / med:.1f})\")\n\n    # measured SLO capacity bracket \u2014 full windows only; a partial rung is\n    # orientation, not evidence\n    rungs = [r for r in rungs if not r.partial]\n    passes = [r.pop for r in rungs if r.passed]\n    fails = [r.pop for r in rungs if not r.passed]\n    lo = max(passes) if passes else None\n    hi = min(fails) if fails else None\n    print(\"\\nMEASURED SLO CAPACITY \"\n          f\"(p{p} TTFT <= {slo['ttft_budget_s']:g}s AND per-user p50 decode \"\n          f\">= {slo['itl_floor_tok_s']:g} tok/s):\")\n    if lo is not None and hi is not None:\n        print(f\"  in ({lo}, {hi}] \u2014 largest passing population {lo} users\")\n    elif lo is not None:\n        print(f\"  >= {lo} users (no failing rung observed \u2014 a lower bound)\")\n    elif hi is not None:\n        print(f\"  < {hi} users (no passing rung observed)\")\n    else:\n        print(\"  not measured\")\n\n    # failure-mode split: which ceilings did the ladder actually see?\n    ttft_fails = [r.pop for r in rungs\n                  if any(\"TTFT\" in s for s in r.reasons)]\n    dec_fails = [r.pop for r in rungs\n                 if any(\"decode\" in s for s in r.reasons)]\n    lat_lo = max((r.pop for r in rungs\n                  if r.passed or not any(\"TTFT\" in s for s in r.reasons)),\n                 default=None)\n    dec_lo = max((r.pop for r in rungs\n                  if r.passed or not any(\"decode\" in s for s in r.reasons)),\n                 default=None)\n\n    print(\"\\nPREDICTED vs MEASURED\")\n    print(f\"{'quantity':<28} {'predicted':>10} {'measured':>22}  verdict\")\n\n    def row(name, predicted, measured, verdict, note):\n        print(f\"{name:<28} {predicted:>10} {measured:>22}  {verdict}  {note}\")\n\n    # binding limit\n    v, note = bracket_verdict(pred.get(\"predicted_limit_users\"), lo, hi)\n    row(f\"SLO capacity ({pred.get('binding_constraint', '?')} binds)\",\n        f\"{pred.get('predicted_limit_users', '-')}\",\n        (f\"({lo},{hi}]\" if lo is not None and hi is not None\n         else f\">={lo}\" if lo is not None else f\"<{hi}\" if hi is not None else \"-\"),\n        v, note)\n\n    # latency ceiling: separable only if a rung failed on TTFT\n    if ttft_fails:\n        v, note = bracket_verdict(pred.get(\"latency_ceiling_users\"),\n                                  lat_lo, min(ttft_fails))\n        row(\"latency ceiling\", f\"{pred.get('latency_ceiling_users', '-')}\",\n            f\"({lat_lo},{min(ttft_fails)}]\", v, note)\n    else:\n        row(\"latency ceiling\", f\"{pred.get('latency_ceiling_users', '-')}\",\n            \"not separable\", TILDE, \"no TTFT-mode failure observed\")\n\n    # decode ceiling: separable only if a rung failed on the floor\n    if dec_fails:\n        v, note = bracket_verdict(pred.get(\"decode_ceiling_users\"),\n                                  dec_lo, min(dec_fails))\n        row(\"decode ceiling\", f\"{pred.get('decode_ceiling_users', '-')}\",\n            f\"({dec_lo},{min(dec_fails)}]\", v, note)\n    else:\n        row(\"decode ceiling\", f\"{pred.get('decode_ceiling_users', '-')}\",\n            \"not separable\", TILDE, \"no decode-floor failure observed\")\n\n    # saturation: visible as achieved req/s falling well under the offered rate\n    sat_evidence = [r for r in rungs if not r.passed and r.n_turns > 0\n                    and math.isfinite(r.achieved_rps)\n                    and r.achieved_rps < 0.7 * r.offered_rps]\n    if sat_evidence:\n        r0 = min(sat_evidence, key=lambda r: r.pop)\n        row(\"saturation ceiling\", f\"{pred.get('saturation_ceiling_users', '-')}\",\n            f\"<= {r0.pop}\", TILDE,\n            f\"achieved {r0.achieved_rps:.2f} req/s vs offered \"\n            f\"{r0.offered_rps:.2f} \u2014 throughput plateau\")\n    else:\n        row(\"saturation ceiling\", f\"{pred.get('saturation_ceiling_users', '-')}\",\n            \"not separable\", TILDE,\n            \"closed loop throttles before duty=100% is visible\")\n\n    # warm capacity: bounded below by the largest population whose hit turns\n    # stayed warm (low effective-cold fraction), never bounded above here\n    held = [r.pop for r in rungs if r.n_hit > 0\n            and (not math.isfinite(r.evict_frac) or r.evict_frac < 0.05)]\n    wc = pred.get(\"warm_capacity_p5\")\n    if held:\n        bound = max(held)\n        if wc is not None and bound >= wc:\n            row(\"warm capacity (p5)\", f\"{wc}\", f\">= {bound}\", CHECK,\n                \"held at/above prediction with <5% effective-cold hits (lower bound)\")\n        else:\n            row(\"warm capacity (p5)\", f\"{wc}\", f\">= {bound}\", TILDE,\n                \"lower bound only \u2014 eviction not reached\")\n    else:\n        evicted = [r for r in rungs if math.isfinite(r.evict_frac)\n                   and r.evict_frac >= 0.05]\n        if evicted:\n            r0 = min(evicted, key=lambda r: r.pop)\n            v = (CROSS if wc is not None and r0.pop < 0.75 * wc else TILDE)\n            row(\"warm capacity (p5)\", f\"{wc}\", f\"< ~{r0.pop}\", v,\n                f\"{r0.evict_frac:.0%} of hit turns re-prefilled at {r0.pop} users\")\n        else:\n            row(\"warm capacity (p5)\", f\"{wc}\", \"not separable\", TILDE, \"no data\")\n\n    # miss TTFT level \u2014 read at the rung nearest the OPERATING POINT the\n    # prediction was computed at (the explorer's Concurrent-users setting):\n    # ttft_miss rises steeply with load, so sampling it at the predicted\n    # LIMIT instead systematically failed a correct model\n    tm = pred.get(\"ttft_miss_s\")\n    cand = [r for r in rungs if r.n_miss > 0 and math.isfinite(r.ttft_miss_mean)]\n    if cand and tm:\n        tgt = (pred.get(\"operating_point_users\")\n               or pred.get(\"predicted_limit_users\") or cand[-1].pop)\n        r0 = min(cand, key=lambda r: abs(r.pop - tgt))\n        ratio = r0.ttft_miss_mean / tm\n        v = CHECK if 0.7 <= ratio <= 1.3 else (TILDE if 0.5 <= ratio <= 2.0 else CROSS)\n        row(\"miss mean TTFT\", f\"{tm:g}s\", f\"{r0.ttft_miss_mean:.2f}s @ {r0.pop}u\",\n            v, f\"{ratio:.2f}x predicted at the ~{tgt}-user operating point \"\n               f\"(model quotes order-of-magnitude bounds)\")\n    else:\n        row(\"miss mean TTFT\", f\"{tm if tm else '-'}\", \"not separable\", TILDE,\n            \"no forced-miss samples\")\n\n    # B* (burst mode only)\n    bstar = pred.get(\"bstar_misses\")\n    b = state.get(\"burst\")\n    if b and b.get(\"last_ttft_s\") is not None:\n        within = b[\"n\"] <= (bstar or 0)\n        met = b[\"last_ttft_s\"] <= slo[\"ttft_budget_s\"]\n        v = CHECK if within == met else (\n            TILDE if bstar and 0.75 <= b[\"n\"] / bstar <= 1.33 else CROSS)\n        row(\"B* (burst tolerance)\", f\"{bstar}\",\n            f\"N={b['n']}: last {b['last_ttft_s']:.2f}s\", v,\n            (\"burst <= B* drained inside budget\" if within and met else\n             \"burst > B* breached budget, as predicted\" if not within and not met else\n             \"outcome contradicts B*\"))\n    else:\n        row(\"B* (burst tolerance)\", f\"{bstar}\", \"not measured\", TILDE,\n            \"run with --burst N to probe the correlated-flush tolerance\")\n\n    # ------------------------------------------------------------------\n    print(\"\\nWHAT THIS RUN DOES NOT ESTABLISH\")\n    notes = [\n        \"Warm capacity is bounded BELOW only: unless a rung shows >5% \"\n        \"effective-cold hit turns, the pool was never driven to eviction, and \"\n        \"the eviction classifier itself is the baseline's 0.4x-cold TTFT \"\n        \"heuristic, not a pool measurement.\",\n        \"Ceilings the ladder did not fail on are 'not separable': one run \"\n        \"observes one binding constraint, not four.\",\n        \"Token counts are chars/{:g} approximations; the achieved/intended \"\n        \"ratio above says how far off \u2014 re-run calibrated before trusting \"\n        \"capacity numbers to better than ~15%.\".format(args.chars_per_token),\n        \"Think time is exponential around a fixed mean; real agentic cadence \"\n        \"is burstier (lognormal sigma 2.43 in the measured trace), which \"\n        \"moves the latency ceiling down, not up.\",\n        \"One seed, one window per rung: no variance estimate. Steady state is \"\n        \"assumed after the ramp, not verified.\",\n        \"DP deployments: this drives ONE endpoint; replica-splitting and \"\n        \"session-sticky routing are not exercised.\",\n    ]\n    wl_n = cfg[\"workload\"]\n    sub_floor = (wl_n[\"system_prefix_tokens\"]\n                 if wl_n.get(\"sub_shares_prefix\", False)\n                 else wl_n.get(\"subagent_prefix_tokens\", 3_000))\n    if sub_floor >= wl_n[\"subagent_median_tokens\"]:\n        notes.append(\n            \"Subagent leg is DEGENERATE under this config: the prefix floor \"\n            f\"({sub_floor:,} tok) >= the subagent median \"\n            f\"({wl_n['subagent_median_tokens']:,} tok), so most subagent \"\n            \"first turns are byte-identical and vLLM dedups them to one \"\n            \"cache entry \u2014 the subagent KV load is not being exercised.\")\n    if not state.get(\"burst\"):\n        notes.append(\"Correlated-flush tolerance (B*) needs the separate \"\n                     \"--burst mode; the ladder's independent per-turn misses \"\n                     \"cannot see it.\")\n    for s in notes:\n        print(f\"  - {s}\")\n\n    if args.json:\n        out = {\n            \"config\": cfg,\n            \"rungs\": [vars(r) for r in rungs],\n            \"burst\": state.get(\"burst\"),\n            \"measured_capacity_bracket\": [lo, hi],\n            \"interrupted\": interrupted,\n        }\n        with open(args.json, \"w\") as f:\n            json.dump(out, f, indent=2, default=str)\n        print(f\"\\nraw results written to {args.json}\")\n\n\n# ============================================================================\n# ladder construction + dry-run self-check\n# ============================================================================\ndef build_ladder(args, cfg) -> list:\n    pred = cfg[\"predictions\"][\"predicted_limit_users\"]\n    mults = [float(x) for x in args.rungs.split(\",\") if x.strip()]\n    pops = {max(1, round(m * pred)) for m in mults}\n    # always ladder THROUGH the operating point: ttft_miss_s (and B*) are\n    # predictions AT that load, so the verdict needs a rung there\n    op = cfg[\"predictions\"].get(\"operating_point_users\")\n    if op:\n        pops.add(max(1, round(op)))\n    return [p for p in sorted(pops) if p <= args.max_users]\n\n\ndef dry_run(args, cfg) -> int:\n    \"\"\"Offline plan + sampler self-check. Exercised in CI-style: exits nonzero\n    if the log-normal sampler drifts from its configured median/sigma.\"\"\"\n    wl, slo, pred = cfg[\"workload\"], cfg[\"slo\"], cfg[\"predictions\"]\n    ep = cfg[\"endpoint\"]\n    print(\"DRY RUN \u2014 plan only, no requests sent\\n\")\n    print(f\"endpoint : {args.base_url or ep['base_url']}  \"\n          f\"model={args.model or ep['model']}  \"\n          f\"api key from ${args.api_key_env or ep['api_key_env']}\")\n    print(f\"SLOs     : p{slo['percentile']} TTFT <= {slo['ttft_budget_s']:g}s, \"\n          f\"per-user p50 decode >= {slo['itl_floor_tok_s']:g} tok/s\")\n\n    print(\"\\nLOAD LADDER (users; each rung: \"\n          f\"ramp {args.ramp_s:g}s + measure {args.measure_s:g}s)\")\n    ladder = build_ladder(args, cfg)\n    print(f\"{'users':>8} {'+sub':>6} {'offered req/s':>14}\")\n    for pop in ladder:\n        n_sub = round(pop * wl[\"subagent_ratio\"])\n        print(f\"{pop:>8} {n_sub:>6} {(pop + n_sub) / wl['think_time_s']:>14.2f}\")\n    est = len(ladder) * (args.ramp_s + args.measure_s)\n    print(f\"full-ladder wall clock (no early stop): ~{est / 60:.0f} min\")\n\n    # sampler self-check: the sampled raw median and log-sd must reproduce the\n    # configured (median, sigma) \u2014 this is the distribution warm capacity and\n    # the prefill tail are priced on, so the harness must draw it faithfully\n    print(\"\\nPROMPT-LENGTH SAMPLER (n=20,000 per class; tokens, \"\n          f\"clipped to [prefix, {args.context_cap_tokens:,}])\")\n    rng = random.Random(args.seed)\n    failed = False\n    hdr = (f\"{'class':<10} {'median cfg':>10} {'median smp':>10} \"\n           f\"{'sigma cfg':>9} {'sigma smp':>9} {'p5':>8} {'p50':>8} \"\n           f\"{'p95':>9} {'mean':>9}  check\")\n    print(hdr)\n    # per-class clip floor, mirroring user_loop: subagents clip to THEIR\n    # prefix unless sub_shares_prefix \u2014 displaying both classes at the user\n    # floor overstated the subagent p50 by ~87% under the default config\n    sub_floor = (wl[\"system_prefix_tokens\"]\n                 if wl.get(\"sub_shares_prefix\", False)\n                 else wl.get(\"subagent_prefix_tokens\", 3_000))\n    for cls, med, sig, floor in (\n            (\"user\", wl[\"user_prompt_median_tokens\"],\n             wl[\"user_prompt_sigma\"], wl[\"system_prefix_tokens\"]),\n            (\"subagent\", wl[\"subagent_median_tokens\"],\n             wl[\"subagent_sigma\"], sub_floor)):\n        raw = [rng.lognormvariate(math.log(med), sig) for _ in range(20_000)]\n        smp_med = pct(raw, 50)\n        logs = [math.log(x) for x in raw]\n        mu = sum(logs) / len(logs)\n        smp_sig = math.sqrt(sum((x - mu) ** 2 for x in logs) / (len(logs) - 1))\n        clipped = [min(max(x, floor), args.context_cap_tokens) for x in raw]\n        ok = (abs(smp_med / med - 1) < 0.03 and abs(smp_sig / sig - 1) < 0.03)\n        failed |= not ok\n        print(f\"{cls:<10} {med:>10,.0f} {smp_med:>10,.0f} {sig:>9.2f} \"\n              f\"{smp_sig:>9.3f} {pct(clipped, 5):>8,.0f} {pct(clipped, 50):>8,.0f} \"\n              f\"{pct(clipped, 95):>9,.0f} {sum(clipped) / len(clipped):>9,.0f}  \"\n              f\"{'PASS' if ok else 'FAIL'}\")\n    print(f\"(chars per token: {args.chars_per_token:g}; a p50 user prompt is \"\n          f\"~{pct([min(max(x, wl['system_prefix_tokens']), args.context_cap_tokens) for x in [wl['user_prompt_median_tokens']]], 50) * args.chars_per_token / 1e3:,.0f}k chars on the wire)\")\n\n    print(\"\\nPREDICTIONS UNDER TEST\")\n    for k in (\"warm_capacity_p5\", \"decode_ceiling_users\", \"latency_ceiling_users\",\n              \"saturation_ceiling_users\", \"binding_constraint\",\n              \"predicted_limit_users\", \"ttft_miss_s\", \"bstar_misses\",\n              \"steady_decode_seqs\", \"steady_decode_tok_s\",\n              \"itl_normal_ms\", \"itl_worst_freeze_ms\"):\n        if pred.get(k) is not None:\n            print(f\"  {k:<26} {pred.get(k)}\")\n    print(\"\\nHYPOTHESES\")\n    for h in cfg[\"hypotheses\"]:\n        print(f\"  - {h}\")\n    if args.burst:\n        burst_pop = args.burst_users or max(1, round(\n            pred.get(\"operating_point_users\")\n            or 0.5 * pred[\"predicted_limit_users\"]))\n        print(f\"\\n--burst {args.burst}: would run the burst probe instead of \"\n              f\"the ladder (standing load {burst_pop} users)\")\n    if failed:\n        print(\"\\nSAMPLER SELF-CHECK FAILED\", file=sys.stderr)\n        return 1\n    print(\"\\nsampler self-check PASSED; run without --dry-run to measure\")\n    return 0\n\n\n# ============================================================================\n# main\n# ============================================================================\ndef parse_args(argv=None):\n    ap = argparse.ArgumentParser(\n        prog=\"validate_deployment.py\",\n        description=\"Closed-loop load harness that tests the capacity model's \"\n                    \"predictions (CONFIG block) against a live vLLM endpoint.\",\n        epilog=\"Examples:\\n\"\n               \"  uv run validate_deployment.py --dry-run\\n\"\n               \"  uv run validate_deployment.py --base-url http://gpu-node:8000/v1\\n\"\n               \"  uv run validate_deployment.py --rungs 0.5,1,1.5 --measure-s 300\\n\"\n               \"  uv run validate_deployment.py --burst 8 --burst-users 100\\n\",\n        formatter_class=argparse.RawDescriptionHelpFormatter)\n    ap.add_argument(\"--base-url\", default=None,\n                    help=\"override CONFIG endpoint base URL (e.g. http://host:8000/v1)\")\n    ap.add_argument(\"--model\", default=None, help=\"override CONFIG model name\")\n    ap.add_argument(\"--api-key-env\", default=None,\n                    help=\"env var holding the API key (default: CONFIG's)\")\n    ap.add_argument(\"--dry-run\", action=\"store_true\",\n                    help=\"print the plan, sampler self-check and hypotheses; \"\n                         \"send nothing (works offline)\")\n    ap.add_argument(\"--rungs\", default=DEFAULT_RUNGS,\n                    help=\"ladder multipliers of predicted_limit_users \"\n                         f\"(default {DEFAULT_RUNGS})\")\n    ap.add_argument(\"--max-users\", type=int, default=1024,\n                    help=\"hard cap on any rung's population (default 1024)\")\n    ap.add_argument(\"--turns-per-user\", type=int, default=0,\n                    help=\"cap turns per session, 0 = unlimited within the window\")\n    ap.add_argument(\"--ramp-s\", type=float, default=90.0,\n                    help=\"per-rung ramp (sessions establish; not measured) \"\n                         \"(default 90)\")\n    ap.add_argument(\"--measure-s\", type=float, default=180.0,\n                    help=\"per-rung steady-state measure window (default 180)\")\n    ap.add_argument(\"--burst\", type=int, default=0, metavar=\"N\",\n                    help=\"run the B* probe instead of the ladder: from steady \"\n                         \"standing load, fire N simultaneous forced misses\")\n    ap.add_argument(\"--burst-users\", type=int, default=0,\n                    help=\"standing load for --burst (default: \"\n                         \"operating_point_users, else 0.5 x \"\n                         \"predicted_limit_users)\")\n    ap.add_argument(\"--chars-per-token\", type=float, default=4.0,\n                    help=\"synthetic-text calibration; the report prints the \"\n                         \"achieved ratio to correct it (default 4.0)\")\n    ap.add_argument(\"--context-cap-tokens\", type=int,\n                    # the explorer writes the configuration's own max_seq_len\n                    # cap into CONFIG; the flag still overrides it\n                    default=CONFIG[\"workload\"].get(\"context_cap_tokens\", 180_000),\n                    help=\"truncation cap on sampled contexts, the model's \"\n                         \"max_seq_len analogue (default: CONFIG, else 180000)\")\n    ap.add_argument(\"--request-timeout-s\", type=float, default=300.0,\n                    help=\"per-request read timeout; keep well above the TTFT \"\n                         \"budget so breaches are measured, not dropped (default 300)\")\n    ap.add_argument(\"--freeze-threshold-ms\", type=float, default=100.0,\n                    metavar=\"MS\",\n                    help=\"an inter-token gap at or above this counts as a \"\n                         \"FREEZE (default 100). Absolute on purpose: it must \"\n                         \"mean the same thing in both arms of an A/B. Keep it \"\n                         \"BELOW the smaller predicted freeze, or the better \"\n                         \"arm reads as zero freezes; the report warns when it \"\n                         \"does not, and the freeze ladder is threshold-free.\")\n    ap.add_argument(\"--seed\", type=int, default=0, help=\"RNG seed (default 0)\")\n    ap.add_argument(\"--no-ignore-eos\", action=\"store_true\",\n                    help=\"drop the vLLM ignore_eos extension (strict OpenAI \"\n                         \"endpoints); decode tok/s then depends on natural EOS\")\n    ap.add_argument(\"--json\", default=None, metavar=\"PATH\",\n                    help=\"also write raw rung results as JSON\")\n    return ap.parse_args(argv)\n\n\nasync def main_async(args, cfg, state: dict):\n    import httpx  # lazy: --dry-run must work without any dependency installed\n\n    limits = httpx.Limits(max_connections=4096, max_keepalive_connections=256)\n    async with httpx.AsyncClient(limits=limits) as client:\n        if args.burst:\n            await run_burst(client, args, cfg, state)\n            return\n        ladder = build_ladder(args, cfg)\n        print(f\"ladder: {ladder} users \"\n              f\"(ramp {args.ramp_s:g}s + measure {args.measure_s:g}s each)\")\n        for pop in ladder:\n            print(f\"\\n--- rung: {pop} users ---\")\n            res = await run_rung(client, args, cfg, pop, state)\n            verdict = \"PASS\" if res.passed else \"FAIL (\" + \"; \".join(res.reasons) + \")\"\n            print(f\"  TTFT hit p50 {fmt(res.ttft_hit_p50, 's')} / miss p50 \"\n                  f\"{fmt(res.ttft_miss_p50, 's')} | all p\"\n                  f\"{cfg['slo']['percentile']} {fmt(res.ttft_all_pX, 's')} | \"\n                  f\"decode p50 {fmt(res.decode_p50, ' tok/s', 1)} | \"\n                  f\"{fmt(res.achieved_rps, ' req/s')} | {verdict}\")\n            if res.blown:\n                print(\"  SLOs clearly blown \u2014 stopping the ladder early \"\n                      \"(higher rungs would only stress the endpoint)\")\n                break\n\n\ndef main(argv=None) -> int:\n    args = parse_args(argv)\n    cfg = CONFIG\n    if args.dry_run:\n        return dry_run(args, cfg)\n\n    # one byte-identical prefix for every session in the process \u2014 the whole\n    # point: vLLM's prefix cache must be able to dedup it across sessions\n    state = {\n        \"rungs\": [],\n        \"current\": None,\n        \"burst\": None,\n        \"system_prefix\": make_text(random.Random(0xC0FFEE),\n                                   cfg[\"workload\"][\"system_prefix_tokens\"],\n                                   args.chars_per_token),\n        # the subagents' own lean prefix \u2014 a DIFFERENT byte-stable block,\n        # deduplicated among subagents only (used unless sub_shares_prefix)\n        \"sub_prefix\": make_text(random.Random(0x5AB4EF1C),\n                                cfg[\"workload\"].get(\"subagent_prefix_tokens\", 3_000),\n                                args.chars_per_token),\n    }\n    interrupted = False\n    try:\n        asyncio.run(main_async(args, cfg, state))\n    except KeyboardInterrupt:\n        interrupted = True\n    print_report(state, cfg, args, interrupted=interrupted)\n    return 130 if interrupted else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n";
